const item = $input.first().json;
const raw = item.body ?? item;
const body = typeof raw === 'string' ? JSON.parse(raw) : raw;
const phone = String(body.phone || body.from || body.sender || body.wa_id || '').trim();
const text = String(body.body || body.text || body.message || '').trim();
const externalMessageId = String(body.external_message_id || body.message_id || body.id || `wacrm-${Date.now()}`).trim();
const externalConversationId = String(body.external_conversation_id || body.conversation_id || body.thread_id || phone || externalMessageId).trim();
if (!phone || !text) {
  throw new Error(`Normalize payload: missing phone or body (keys: ${Object.keys(body).join(',')})`);
}
return [{
  json: {
    tenant_slug: 'peskids',
    provider: 'wacrm',
    event_type: body.event_type || 'inbound_message',
    external_conversation_id: externalConversationId,
    external_message_id: externalMessageId,
    phone,
    contact_name: body.contact_name || body.name || body.pushName || 'Contacto WhatsApp',
    body: text,
    direction: body.direction || 'inbound',
    timestamp: body.timestamp || new Date().toISOString(),
    metadata: body.metadata || {}
  }
}];
